    [],
  );

  const metricLabel =
    metric === "top1"
      ? "Top-1 share %"
      : metric === "top3"
        ? "Top-3 share %"
        : "HHI";

  const metricValue = (row: (typeof ladderBars)[0]) =>
    metric === "top1"
