                    tick={{ fontSize: 11, fill: "#64748b" }}
                    unit="%"
                  />
                  <Tooltip
                    formatter={(v) => [fmtPct(Number(v ?? 0)), slopeLabel]}
                  />
                  <Area
                    type="monotone"
                    dataKey="value"
                    fill={`${AMBER}33`}
                    stroke={AMBER}
                    strokeWidth={2}
                    name={slopeLabel}
                  />
                  <Line
                    type="monotone"
                    dataKey="value"
                    stroke={ROSE}
                    strokeWidth={2}
                    dot={{ r: 5 }}
                  />
