/**
 * QA: fiscal-plumbing-concentration-2026q3
 * // viz-types: Lens ladder bars, Lorenz area+line, trust crossover, HHI donut, leverage scatter, vintage slope + Top-1 deltas | layout: default
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { chromium } from "playwright";
import { startStaticServer, stopStaticServer } from "./lib/static-server.mjs";
import { auditVizInteractions } from "./lib/viz-interaction-qa.mjs";
import {
  HEADLINE,
  LENS_COMPARE,
  OFF_BALANCE_SHARES,
  TE_SHARES,
  TRUST_SHARES,
  VINTAGE_SLOPE,
} from "../src/data/fiscal-plumbing-concentration-2026q3-data.ts";

assert.equal(HEADLINE.teTop1Pct, 15.8);
assert.equal(HEADLINE.teTop3Pct, 37.6);
assert.equal(HEADLINE.teUniverseTn, 2.51);
assert.equal(HEADLINE.trustTop1Pct, 54.3);
assert.equal(HEADLINE.offTop3Pct, 91.2);
assert.equal(HEADLINE.offStockTn, 23.55);
assert.equal(TE_SHARES[0].short, "Pensions");
assert.equal(TRUST_SHARES[0].short, "OASI");
assert.equal(OFF_BALANCE_SHARES[0].short, "FDIC DI");
assert.ok(LENS_COMPARE.length >= 4);
assert.equal(VINTAGE_SLOPE.length, 2);

const root = process.cwd();
const slug = "fiscal-plumbing-concentration-2026q3";
const markers = [
  "Fiscal plumbing ??? Q3 2026 concentration lens",
  "Top-3 share % across plumbing lenses",
  "HHI band mix",
];

async function clickBtn(page, name) {
  console.log(`??? click ${name}`);
  await page.locator("button", { hasText: name }).first().click({ timeout: 8000 });
  await page.waitForTimeout(150);
}

async function main() {
  const outDir = path.join(root, "out");
  if (!fs.existsSync(outDir)) {
    console.error("??? Missing out/ ??? run npm run build first");
    process.exit(1);
  }
  const port = Number(process.env.SMOKE_PORT || 4182);
  const server = await startStaticServer(outDir, port);
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  page.setDefaultTimeout(15000);
  try {
    await page.goto(`http://127.0.0.1:${port}/blog/${slug}.html`, {
      waitUntil: "domcontentloaded",
      timeout: 45000,
    });
    await page.waitForSelector(
      '[data-viz="fiscal-plumbing-concentration-2026q3"]',
      { timeout: 20000 },
    );
